function makeFareDedupKey(row) {
  const pallet = getTotalPalletFromOrder(row);
  const fare = Number(String(row.청구운임 || "0").replace(/[^\d]/g, ""));

  return [
    row.상차지명?.trim(),
row.하차지명?.trim(),
    pallet ?? "",              // ★ 파렛트 수
    row.차량종류 || "",        // ★ 차량종류
    fare                        // ★ 청구운임
  ].join("|");
}
