function generateTimeOptions() {
  const result = [];
  for (let h = 0; h < 24; h++) {
    for (let m of [0, 30]) {
      const isPM = h >= 12;
      const hour12 = h % 12 === 0 ? 12 : h % 12;
      result.push(`${isPM ? "오후" : "오전"} ${hour12}시${m === 30 ? " 30분" : ""}`);
    }
  }
  return result;
}
